        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน วอชิงตัน (สหรัฐอเมริกา) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว แปซิฟิกนอร์ทเวสต์ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Washington (United States), serving as the spiritual heart of ancestral แปซิฟิกนอร์ทเวสต์ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค วอชิงตัน (สหรัฐอเมริกา) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Washington (United States), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน โอลิมปิก',
        'Remove footwear and maintain silence within the inner terrace of Olympic.',
        'https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg',
        0,
