        '[{"type":"image","url":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg","title":"เทวสถานศรัทธาแห่งแสงธรรม โอลิมปิก (แปซิฟิกนอร์ทเวสต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KsnE0OGg2tk","title":"ตำนาน ปูชนียสถานศักดิ์สิทธิ์และบารมีพระบรมธาตุ","thumbnail":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg"}]'
