        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-olympic-5-41',
        'เงาร่างทมิฬแห่งหอระฆังร้าง โอลิมปิก (แปซิฟิกนอร์ทเวสต์)',
