        'legend',
        'วอชิงตัน (สหรัฐอเมริกา)',
        'Washington (United States)',
        'โอลิมปิก',
        'Olympic',
        47.8471,
        -123.5894,
        'jungle_curse',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง วอชิงตัน (สหรัฐอเมริกา) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว แปซิฟิกนอร์ทเวสต์ ใน โอลิมปิก',
        'A legendary monumental marvel in Washington (United States). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral แปซิฟิกนอร์ทเวสต์ engineers in Olympic.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ วอชิงตัน (สหรัฐอเมริกา) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Washington (United States), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ โอลิมปิก',
        'Do not deface, carve, or displace ancient stones in Olympic.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"นครโบราณที่สาบสูญใต้ผืนป่า โอลิมปิก (แปซิฟิกนอร์ทเวสต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

