        -38.5166,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น บาเอีย (บราซิล) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ ซัลวาดอร์',
        'A chilling paranormal account from Bahia (Brazil). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Salvador.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว กานดงเบล ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of กานดงเบล oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ ซัลวาดอร์',
        'Never whistle or look back if hearing whispers along twilight pathways in Salvador.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"เงาไร้หน้าที่บานหน้าต่างค่ำคืน ซัลวาดอร์ (กานดงเบล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-salvador-5-45',
        'ปีศาจจำแลงร่างล่อลวงคนเดินทาง ซัลวาดอร์ (กานดงเบล)',
        'The Deceptive Shapeshifting Stalker of Salvador (กานดงเบล)',
        'monster',
        'บาเอีย (บราซิล)',
        'Bahia (Brazil)',
        'ซัลวาดอร์',
        'Salvador',
        -12.9777,
        -38.5166,
        'whisper',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน บาเอีย (บราซิล) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ซัลวาดอร์',
        'Eyewitness reports of a formidable cryptid stalking Bahia (Brazil). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Salvador.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว กานดงเบล ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native กานดงเบล folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ซัลวาดอร์',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Salvador.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"ปีศาจจำแลงร่างล่อลวงคนเดินทาง ซัลวาดอร์ (กานดงเบล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-salvador-5-45',
        'อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป ซัลวาดอร์ (กานดงเบล)',
        'The Spectral Vessel Curse of Salvador (กานดงเบล)',
        'curse',
        'บาเอีย (บราซิล)',
        'Bahia (Brazil)',
        'ซัลวาดอร์',
        'Salvador',
        -12.9777,
        -38.5166,
        'water_spirit',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง บาเอีย (บราซิล) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ซัลวาดอร์',
        'A grim cautionary curse chronicle from Bahia (Brazil). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Salvador.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว กานดงเบล เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of กานดงเบล, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ซัลวาดอร์',
        'Never remove stones, relics, or votive offerings from Salvador.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป ซัลวาดอร์ (กานดงเบล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-salvador-5-45',
        'กำแพงศิลาและป้อมปราการแห่งกษัตริย์ ซัลวาดอร์ (กานดงเบล)',
        'The Cyclopean Stone Fortresses of Salvador (กานดงเบล)',
        'legend',
        'บาเอีย (บราซิล)',
        'Bahia (Brazil)',
        'ซัลวาดอร์',
        'Salvador',
        -12.9777,
        -38.5166,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง บาเอีย (บราซิล) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว กานดงเบล ใน ซัลวาดอร์',
        'A legendary monumental marvel in Bahia (Brazil). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral กานดงเบล engineers in Salvador.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ บาเอีย (บราซิล) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Bahia (Brazil), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ซัลวาดอร์',
        'Do not deface, carve, or displace ancient stones in Salvador.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"กำแพงศิลาและป้อมปราการแห่งกษัตริย์ ซัลวาดอร์ (กานดงเบล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
