INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-table-mountain-5-49',
        'เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน เทเบิลเมาน์เทน (คอยซาน)',
        'The Midnight Footsteps of Table Mountain (คอยซาน)',
        'ghost',
        'เคปทาวน์ (แอฟริกาใต้)',
        'Cape Town (South Africa)',
        'เทเบิลเมาน์เทน',
        'Table Mountain',
        -34.0078,
        18.3647,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น เคปทาวน์ (แอฟริกาใต้) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ เทเบิลเมาน์เทน',
        'A chilling paranormal account from Cape Town (South Africa). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Table Mountain.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว คอยซาน ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of คอยซาน oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ เทเบิลเมาน์เทน',
        'Never whistle or look back if hearing whispers along twilight pathways in Table Mountain.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-table-mountain-5-49',
        'พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน เทเบิลเมาน์เทน (คอยซาน)',
        'The Black-Scaled Serpent of Table Mountain (คอยซาน)',
        'monster',
        'เคปทาวน์ (แอฟริกาใต้)',
        'Cape Town (South Africa)',
        'เทเบิลเมาน์เทน',
        'Table Mountain',
        -34.0078,
        18.3647,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เคปทาวน์ (แอฟริกาใต้) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เทเบิลเมาน์เทน',
        'Eyewitness reports of a formidable cryptid stalking Cape Town (South Africa). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Table Mountain.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว คอยซาน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native คอยซาน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เทเบิลเมาน์เทน',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Table Mountain.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-table-mountain-5-49',
        'อาถรรพ์รูปเคารพและดวงตาจ้องมอง เทเบิลเมาน์เทน (คอยซาน)',
        'The Cursed Effigy Gaze of Table Mountain (คอยซาน)',
        'curse',
        'เคปทาวน์ (แอฟริกาใต้)',
        'Cape Town (South Africa)',
        'เทเบิลเมาน์เทน',
        'Table Mountain',
        -34.0078,
        18.3647,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เคปทาวน์ (แอฟริกาใต้) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เทเบิลเมาน์เทน',
        'A grim cautionary curse chronicle from Cape Town (South Africa). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Table Mountain.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว คอยซาน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of คอยซาน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เทเบิลเมาน์เทน',
        'Never remove stones, relics, or votive offerings from Table Mountain.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"อาถรรพ์รูปเคารพและดวงตาจ้องมอง เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-table-mountain-5-49',
        'รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ เทเบิลเมาน์เทน (คอยซาน)',
        'The Undeciphered Glyph Stele of Table Mountain (คอยซาน)',
        'legend',
        'เคปทาวน์ (แอฟริกาใต้)',
        'Cape Town (South Africa)',
        'เทเบิลเมาน์เทน',
        'Table Mountain',
        -34.0078,
        18.3647,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เคปทาวน์ (แอฟริกาใต้) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว คอยซาน ใน เทเบิลเมาน์เทน',
        'A legendary monumental marvel in Cape Town (South Africa). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral คอยซาน engineers in Table Mountain.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เคปทาวน์ (แอฟริกาใต้) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Cape Town (South Africa), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เทเบิลเมาน์เทน',
        'Do not deface, carve, or displace ancient stones in Table Mountain.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ เทเบิลเมาน์เทน (คอยซาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-kakadu-6-50',
        'มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ คาคาดู (อะบอริจินดรีมไทม์)',
        'The Golden Relic Stupa of Kakadu (อะบอริจินดรีมไทม์)',
        'sacred',
        'นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย)',
        'Northern Territory (Australia)',
        'คาคาดู',
        'Kakadu',
        -12.8633,
        132.8333,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อะบอริจินดรีมไทม์ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Northern Territory (Australia), serving as the spiritual heart of ancestral อะบอริจินดรีมไทม์ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Northern Territory (Australia), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน คาคาดู',
        'Remove footwear and maintain silence within the inner terrace of Kakadu.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ คาคาดู (อะบอริจินดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

