INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-kakadu-6-50',
        'อสุรกายพญาเงาแห่งพงไพร คาคาดู (อะบอริจินดรีมไทม์)',
        'The Shadow Beast of Kakadu (อะบอริจินดรีมไทม์)',
        'monster',
        'นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย)',
        'Northern Territory (Australia)',
        'คาคาดู',
        'Kakadu',
        -12.8633,
        132.8333,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ คาคาดู',
        'Eyewitness reports of a formidable cryptid stalking Northern Territory (Australia). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Kakadu.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว อะบอริจินดรีมไทม์ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native อะบอริจินดรีมไทม์ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ คาคาดู',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Kakadu.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อสุรกายพญาเงาแห่งพงไพร คาคาดู (อะบอริจินดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-kakadu-6-50',
        'คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม คาคาดู (อะบอริจินดรีมไทม์)',
        'The Inscribed Hex and Tragic Fate of Kakadu (อะบอริจินดรีมไทม์)',
        'curse',
        'นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย)',
        'Northern Territory (Australia)',
        'คาคาดู',
        'Kakadu',
        -12.8633,
        132.8333,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน คาคาดู',
        'A grim cautionary curse chronicle from Northern Territory (Australia). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Kakadu.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว อะบอริจินดรีมไทม์ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of อะบอริจินดรีมไทม์, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ คาคาดู',
        'Never remove stones, relics, or votive offerings from Kakadu.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม คาคาดู (อะบอริจินดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-kakadu-6-50',
        'มหาปราการหินเมกะลิธและแนวสุริยะ คาคาดู (อะบอริจินดรีมไทม์)',
        'The Megalithic Solar Alignments of Kakadu (อะบอริจินดรีมไทม์)',
        'legend',
        'นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย)',
        'Northern Territory (Australia)',
        'คาคาดู',
        'Kakadu',
        -12.8633,
        132.8333,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว อะบอริจินดรีมไทม์ ใน คาคาดู',
        'A legendary monumental marvel in Northern Territory (Australia). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral อะบอริจินดรีมไทม์ engineers in Kakadu.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ นอร์ทเทิร์นเทร์ริทอรี (ออสเตรเลีย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Northern Territory (Australia), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ คาคาดู',
        'Do not deface, carve, or displace ancient stones in Kakadu.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"มหาปราการหินเมกะลิธและแนวสุริยะ คาคาดู (อะบอริจินดรีมไทม์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-rotorua-6-51',
        'เทวสถานศรัทธาแห่งแสงธรรม โรโตรัว (เมารี)',
        'The Radiant Divine Sanctuary of Rotorua (เมารี)',
        'sacred',
        'เกาะเหนือ (นิวซีแลนด์)',
        'North Island (New Zealand)',
        'โรโตรัว',
        'Rotorua',
        -38.1519,
        176.2947,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เกาะเหนือ (นิวซีแลนด์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เมารี เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of North Island (New Zealand), serving as the spiritual heart of ancestral เมารี heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เกาะเหนือ (นิวซีแลนด์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in North Island (New Zealand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน โรโตรัว',
        'Remove footwear and maintain silence within the inner terrace of Rotorua.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"เทวสถานศรัทธาแห่งแสงธรรม โรโตรัว (เมารี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
