        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-rotorua-6-51',
        'เงาร่างทมิฬแห่งหอระฆังร้าง โรโตรัว (เมารี)',
        'The Dark Bell Tower Phantom of Rotorua (เมารี)',
        'ghost',
        'เกาะเหนือ (นิวซีแลนด์)',
        'North Island (New Zealand)',
        'โรโตรัว',
        'Rotorua',
        -38.1519,
        176.2947,
        'creepy_wind',
        'เรื่องเล่าสยองขวัญประจำถิ่น เกาะเหนือ (นิวซีแลนด์) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ โรโตรัว',
        'A chilling paranormal account from North Island (New Zealand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Rotorua.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เมารี ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เมารี oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ โรโตรัว',
        'Never whistle or look back if hearing whispers along twilight pathways in Rotorua.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"เงาร่างทมิฬแห่งหอระฆังร้าง โรโตรัว (เมารี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

