        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-pa-sang-6-54',
        'วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ ป่าซาง (หริภุญชัย)',
        'The Crystal Vihara and Consecrated Icon of Pa Sang (หริภุญชัย)',
        'sacred',
        'ลำพูน (ไทย)',
        'Lamphun (Thailand)',
        'ป่าซาง',
        'Pa Sang',
        18.5583,
        98.9089,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ลำพูน (ไทย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว หริภุญชัย เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Lamphun (Thailand), serving as the spiritual heart of ancestral หริภุญชัย heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ลำพูน (ไทย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Lamphun (Thailand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน ป่าซาง',
        'Remove footwear and maintain silence within the inner terrace of Pa Sang.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ ป่าซาง (หริภุญชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

