        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว หริภุญชัย ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native หริภุญชัย folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ป่าซาง',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Pa Sang.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"อมนุษย์กรงเล็บเคียวแห่งหมอกหนาว ป่าซาง (หริภุญชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-pa-sang-6-54',
        'กระจกเงาต้องคำสาปและเงาลวงตา ป่าซาง (หริภุญชัย)',
        'The Cursed Scrying Glass of Pa Sang (หริภุญชัย)',
        'curse',
        'ลำพูน (ไทย)',
        'Lamphun (Thailand)',
        'ป่าซาง',
        'Pa Sang',
        18.5583,
        98.9089,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ลำพูน (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ป่าซาง',
        'A grim cautionary curse chronicle from Lamphun (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Pa Sang.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว หริภุญชัย เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of หริภุญชัย, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ป่าซาง',
        'Never remove stones, relics, or votive offerings from Pa Sang.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"กระจกเงาต้องคำสาปและเงาลวงตา ป่าซาง (หริภุญชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-pa-sang-6-54',
        'เส้นทางค้าโบราณและคาราวานปริศนา ป่าซาง (หริภุญชัย)',
        'The Ancient Silk Route Oasis of Pa Sang (หริภุญชัย)',
        'legend',
        'ลำพูน (ไทย)',
        'Lamphun (Thailand)',
        'ป่าซาง',
        'Pa Sang',
        18.5583,
        98.9089,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ลำพูน (ไทย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว หริภุญชัย ใน ป่าซาง',
        'A legendary monumental marvel in Lamphun (Thailand). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral หริภุญชัย engineers in Pa Sang.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ลำพูน (ไทย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Lamphun (Thailand), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ป่าซาง',
        'Do not deface, carve, or displace ancient stones in Pa Sang.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"เส้นทางค้าโบราณและคาราวานปริศนา ป่าซาง (หริภุญชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
