        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน สุราษฎร์ธานี (ไทย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ทักษิณศรีวิชัย เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Surat Thani (Thailand), serving as the spiritual heart of ancestral ทักษิณศรีวิชัย heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค สุราษฎร์ธานี (ไทย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Surat Thani (Thailand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน เกาะสมุย',
        'Remove footwear and maintain silence within the inner terrace of Ko Samui.',
        'https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg","title":"เทวาลัยโบราณแห่งมหาเทวะ เกาะสมุย (ทักษิณศรีวิชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KsnE0OGg2tk","title":"ตำนาน ปูชนียสถานศักดิ์สิทธิ์และบารมีพระบรมธาตุ","thumbnail":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-ko-samui-6-57',
        'ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ เกาะสมุย (ทักษิณศรีวิชัย)',
        'The Will-o''-the-Wisp Ghost Light of Ko Samui (ทักษิณศรีวิชัย)',
        'ghost',
        'สุราษฎร์ธานี (ไทย)',
        'Surat Thani (Thailand)',
        'เกาะสมุย',
        'Ko Samui',
        9.5057,
        100.06,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น สุราษฎร์ธานี (ไทย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ เกาะสมุย',
        'A chilling paranormal account from Surat Thani (Thailand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Ko Samui.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ทักษิณศรีวิชัย ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ทักษิณศรีวิชัย oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ เกาะสมุย',
        'Never whistle or look back if hearing whispers along twilight pathways in Ko Samui.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ เกาะสมุย (ทักษิณศรีวิชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-ko-samui-6-57',
        'อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด เกาะสมุย (ทักษิณศรีวิชัย)',
        'The Amphibious Troglodyte of Ko Samui (ทักษิณศรีวิชัย)',
        'monster',
        'สุราษฎร์ธานี (ไทย)',
        'Surat Thani (Thailand)',
        'เกาะสมุย',
        'Ko Samui',
        9.5057,
        100.06,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน สุราษฎร์ธานี (ไทย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เกาะสมุย',
        'Eyewitness reports of a formidable cryptid stalking Surat Thani (Thailand). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Ko Samui.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ทักษิณศรีวิชัย ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ทักษิณศรีวิชัย folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เกาะสมุย',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Ko Samui.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด เกาะสมุย (ทักษิณศรีวิชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-ko-samui-6-57',
        'อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม เกาะสมุย (ทักษิณศรีวิชัย)',
        'The Fatal Melody Hex of Ko Samui (ทักษิณศรีวิชัย)',
        'curse',
        'สุราษฎร์ธานี (ไทย)',
        'Surat Thani (Thailand)',
        'เกาะสมุย',
        'Ko Samui',
        9.5057,
        100.06,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง สุราษฎร์ธานี (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เกาะสมุย',
        'A grim cautionary curse chronicle from Surat Thani (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Ko Samui.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ทักษิณศรีวิชัย เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ทักษิณศรีวิชัย, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เกาะสมุย',
        'Never remove stones, relics, or votive offerings from Ko Samui.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม เกาะสมุย (ทักษิณศรีวิชัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
